1	package com.example.starter.api;
2	
3	import com.example.starter.api.dto.ArtifactResponse;
4	import com.example.starter.api.dto.DependencySpec;
5	import com.example.starter.api.dto.DependencyView;
6	import com.example.starter.api.dto.LockEntryResponse;
7	import com.example.starter.api.dto.LockFileResponse;
8	import com.example.starter.api.dto.LockRequest;
9	import com.example.starter.api.dto.RegisterArtifactRequest;
10	import com.example.starter.domain.ArtifactVersion;
11	import com.example.starter.domain.DependencyRange;
12	import com.example.starter.domain.LockResolver;
13	import com.example.starter.domain.RepositorySnapshot;
14	import com.example.starter.repo.RepositoryDao;
15	import com.example.starter.repo.RepositoryDao.IdempotentRecord;
16	import com.example.starter.repo.RepositoryDao.LockEntryRow;
17	import com.example.starter.repo.RepositoryDao.LockFileRow;
18	import com.example.starter.support.ApiException;
19	import com.fasterxml.jackson.databind.ObjectMapper;
20	import org.springframework.dao.DuplicateKeyException;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.support.TransactionTemplate;
23	
24	import java.nio.charset.StandardCharsets;
25	import java.security.MessageDigest;
26	import java.security.NoSuchAlgorithmException;
27	import java.time.Clock;
28	import java.time.Instant;
29	import java.util.ArrayList;
30	import java.util.HashSet;
31	import java.util.List;
32	import java.util.Map;
33	import java.util.Set;
34	import java.util.TreeMap;
35	import java.util.function.Supplier;
36	
37	/**
38	 * 制品仓库业务服务实现。
39	 *
40	 * <p>所有写操作在单个事务内完成：先锁单行仓库版本表互斥并发写，
41	 * 再做业务变更并写入幂等成功记录，原子提交；业务失败整体回滚，不占用 requestId。
42	 */
43	@Service
44	public class ArtifactServiceImpl implements ArtifactService {
45	
46	    private static final int MAX_NAMES = 20;
47	    private static final int MAX_VERSIONS_PER_NAME = 5;
48	
49	    private static final String OP_REGISTER = "REGISTER_ARTIFACT";
50	    private static final String OP_WITHDRAW = "WITHDRAW_ARTIFACT";
51	    private static final String OP_LOCK = "CREATE_LOCK";
52	
53	    private final RepositoryDao repositoryDao;
54	    private final TransactionTemplate transactionTemplate;
55	    private final ObjectMapper objectMapper;
56	    private final Clock clock;
57	
58	    public ArtifactServiceImpl(RepositoryDao repositoryDao,
59	                               TransactionTemplate transactionTemplate,
60	                               ObjectMapper objectMapper,
61	                               Clock clock) {
62	        this.repositoryDao = repositoryDao;
63	        this.transactionTemplate = transactionTemplate;
64	        this.objectMapper = objectMapper;
65	        this.clock = clock;
66	    }
67	
68	    @Override
69	    public ArtifactResponse registerArtifact(String requestId, RegisterArtifactRequest request) {
70	        requireRequestId(requestId);
71	        validateRegisterRequest(request);
72	        String hash = sha256(OP_REGISTER + "|" + request.name().trim() + "|" + request.version() + "|"
73	                + canonicalDependencies(request));
74	        return executeIdempotent(requestId, OP_REGISTER, hash, 201,
75	                () -> doRegister(request), ArtifactResponse.class);
76	    }
77	
78	    @Override
79	    public ArtifactResponse withdrawArtifact(String requestId, String name, int version) {
80	        requireRequestId(requestId);
81	        if (name == null || name.isBlank()) {
82	            throw ApiException.badRequest("name 不能为空");
83	        }
84	        String hash = sha256(OP_WITHDRAW + "|" + name.trim() + "|" + version);
85	        return executeIdempotent(requestId, OP_WITHDRAW, hash, 200,
86	                () -> doWithdraw(name.trim(), version), ArtifactResponse.class);
87	    }
88	
89	    @Override
90	    public LockFileResponse createLock(String requestId, LockRequest request) {
91	        requireRequestId(requestId);
92	        if (request.rootName() == null || request.rootName().isBlank()) {
93	            throw ApiException.badRequest("rootName 不能为空");
94	        }
95	        String hash = sha256(OP_LOCK + "|" + request.rootName().trim() + "|" + request.rootVersion()
96	                + "|" + request.expectedRepositoryVersion());
97	        return executeIdempotent(requestId, OP_LOCK, hash, 201,
98	                () -> doLock(request), LockFileResponse.class);
99	    }
100	
101	    @Override
102	    public List<LockFileResponse> listLocks() {
103	        List<LockFileResponse> result = new ArrayList<>();
104	        for (LockFileRow row : repositoryDao.listLockFiles()) {
105	            result.add(toLockResponse(row, repositoryDao.listLockEntries(row.id())));
106	        }
107	        return result;
108	    }
109	
110	    @Override
111	    public LockFileResponse getLock(long id) {
112	        LockFileRow row = repositoryDao.getLockFile(id);
113	        if (row == null) {
114	            throw ApiException.notFound("锁文件不存在: " + id);
115	        }
116	        return toLockResponse(row, repositoryDao.listLockEntries(id));
117	    }
118	
119	    // ------------------------------------------------------------------
120	    // 业务操作（运行在已加行锁的写事务内）
121	    // ------------------------------------------------------------------
122	
123	    private ArtifactResponse doRegister(RegisterArtifactRequest request) {
124	        String name = request.name().trim();
125	        int version = request.version();
126	
127	        if (repositoryDao.artifactExists(name, version)) {
128	            throw ApiException.conflict("制品版本已存在: " + name + ":" + version);
129	        }
130	        int existingVersions = repositoryDao.countVersions(name);
131	        if (existingVersions == 0 && repositoryDao.countDistinctNames() >= MAX_NAMES) {
132	            throw ApiException.unprocessable(
133	                    "仓库名称数量已达上限 " + MAX_NAMES);
134	        }
135	        if (existingVersions >= MAX_VERSIONS_PER_NAME) {
136	            throw ApiException.unprocessable(
137	                    "制品 " + name + " 的版本数量已达上限 " + MAX_VERSIONS_PER_NAME);
138	        }
139	
140	        Instant now = Instant.now(clock);
141	        long artifactId = repositoryDao.insertArtifact(name, version, now);
142	        for (var dep : request.dependencies()) {
143	            repositoryDao.insertDependency(artifactId, dep.name().trim(),
144	                    dep.minimumVersion(), dep.maximumVersion());
145	        }
146	        long repositoryVersion = repositoryDao.incrementRepositoryVersion();
147	
148	        return new ArtifactResponse(name, version, false, repositoryVersion, now,
149	                toDependencyViews(request.dependencies()));
150	    }
151	
152	    private ArtifactResponse doWithdraw(String name, int version) {
153	        ArtifactVersion artifact = repositoryDao.loadArtifact(name, version);
154	        if (artifact == null) {
155	            throw ApiException.notFound("制品版本不存在: " + name + ":" + version);
156	        }
157	        if (artifact.withdrawn()) {
158	            throw ApiException.conflict("制品版本已撤回: " + name + ":" + version);
159	        }
160	        int affected = repositoryDao.markWithdrawn(artifact.id());
161	        if (affected == 0) {
162	            // 并发撤回抢先提交（持有行锁时理论上不会发生，防御性处理）。
163	            throw ApiException.conflict("制品版本已撤回: " + name + ":" + version);
164	        }
165	        long repositoryVersion = repositoryDao.incrementRepositoryVersion();
166	        return new ArtifactResponse(name, version, true, repositoryVersion,
167	                Instant.now(clock), toDependencyViews(artifact.dependencies()));
168	    }
169	
170	    private LockFileResponse doLock(LockRequest request) {
171	        String rootName = request.rootName().trim();
172	        int rootVersion = request.rootVersion();
173	
174	        // 当前事务已在入口持有 repository_state 行锁；此处读取版本号并做乐观校验。
175	        long currentVersion = repositoryDao.lockRepositoryState();
176	        if (currentVersion != request.expectedRepositoryVersion()) {
177	            throw ApiException.conflict("仓库版本不匹配：expected="
178	                    + request.expectedRepositoryVersion() + ", actual=" + currentVersion);
179	        }
180	
181	        ArtifactVersion root = repositoryDao.loadArtifact(rootName, rootVersion);
182	        if (root == null) {
183	            throw ApiException.notFound("根制品版本不存在: " + rootName + ":" + rootVersion);
184	        }
185	        if (root.withdrawn()) {
186	            throw ApiException.conflict("根制品版本已撤回: " + rootName + ":" + rootVersion);
187	        }
188	
189	        RepositorySnapshot snapshot = repositoryDao.loadSnapshot();
190	        Map<String, Integer> solution = LockResolver.resolve(snapshot, rootName, rootVersion);
191	        if (solution == null) {
192	            throw ApiException.unprocessable(
193	                    "不存在满足全部依赖区间的未撤回版本组合，无法锁定");
194	        }
195	
196	        Instant now = Instant.now(clock);
197	        long lockFileId = repositoryDao.insertLockFile(rootName, rootVersion, currentVersion,
198	                currentRequestId.get(), now);
199	        solution.forEach((n, v) -> repositoryDao.insertLockEntry(lockFileId, n, v));
200	
201	        List<LockEntryResponse> entries = new ArrayList<>();
202	        solution.forEach((n, v) -> entries.add(new LockEntryResponse(n, v)));
203	        return new LockFileResponse(lockFileId, rootName, rootVersion, currentVersion, now, entries);
204	    }
205	
206	    // ------------------------------------------------------------------
207	    // 幂等控制
208	    // ------------------------------------------------------------------
209	
210	    /**
211	     * 当前写事务使用的 requestId，供同事务内的记录写入引用。
212	     */
213	    private final ThreadLocal<String> currentRequestId = new ThreadLocal<>();
214	
215	    private <T> T executeIdempotent(String requestId, String operation, String requestHash,
216	                                    int httpStatus, Supplier<T> action, Class<T> responseType) {
217	        // 快速路径：已提交的成功记录直接重放。
218	        T replay = replayIfPresent(requestId, operation, requestHash, responseType);
219	        if (replay != null) {
220	            return replay;
221	        }
222	
223	        try {
224	            return transactionTemplate.execute(status -> {
225	                // 锁单行仓库版本，串行化全部写事务，保证快照与版本号一致。
226	                repositoryDao.lockRepositoryState();
227	                // 等待行锁期间可能已有同键事务提交，再次检查。
228	                T existing = replayIfPresent(requestId, operation, requestHash, responseType);
229	                if (existing != null) {
230	                    return existing;
231	                }
232	                repositoryDao.insertPendingIdempotentRequest(
233	                        requestId, operation, requestHash, Instant.now(clock));
234	                currentRequestId.set(requestId);
235	                try {
236	                    T result = action.get();
237	                    repositoryDao.completeIdempotentRequest(
238	                            requestId, httpStatus, writeJson(result));
239	                    return result;
240	                } finally {
241	                    currentRequestId.remove();
242	                }
243	            });
244	        } catch (DuplicateKeyException e) {
245	            // 同键并发：赢家已提交则重放其结果，否则报告冲突。
246	            T replayAfterRace = replayIfPresent(requestId, operation, requestHash, responseType);
247	            if (replayAfterRace != null) {
248	                return replayAfterRace;
249	            }
250	            throw ApiException.conflict("相同 requestId 的请求正在处理中: " + requestId);
251	        }
252	    }
253	
254	    /**
255	     * 存在成功记录时：同操作同参返回原结果；异参（含异操作）返回 409。不存在返回 null。
256	     */
257	    private <T> T replayIfPresent(String requestId, String operation, String requestHash,
258	                                  Class<T> responseType) {
259	        IdempotentRecord record = repositoryDao.findIdempotentRequest(requestId);
260	        if (record == null) {
261	            return null;
262	        }
263	        if (!record.operation().equals(operation) || !record.requestHash().equals(requestHash)) {
264	            throw ApiException.conflict(
265	                    "requestId 已用于不同参数的请求: " + requestId);
266	        }
267	        return readJson(record.responseJson(), responseType);
268	    }
269	
270	    // ------------------------------------------------------------------
271	    // 校验与转换
272	    // ------------------------------------------------------------------
273	
274	    private void validateRegisterRequest(RegisterArtifactRequest request) {
275	        if (request.name() == null || request.name().isBlank()) {
276	            throw ApiException.badRequest("name 不能为空");
277	        }
278	        List<DependencySpec> deps = request.dependencies();
279	        if (deps.size() > 10) {
280	            throw ApiException.badRequest("每个制品版本最多声明 10 条依赖");
281	        }
282	        Set<String> names = new HashSet<>();
283	        for (DependencySpec dep : deps) {
284	            if (dep.name() == null || dep.name().isBlank()) {
285	                throw ApiException.badRequest("依赖名称不能为空");
286	            }
287	            String depName = dep.name().trim();
288	            if (dep.minimumVersion() > dep.maximumVersion()) {
289	                throw ApiException.badRequest(
290	                        "依赖 " + depName + " 的最低版本不能高于最高版本");
291	            }
292	            if (!names.add(depName)) {
293	                throw ApiException.badRequest("依赖名称重复: " + depName);
294	            }
295	        }
296	    }
297	
298	    private String canonicalDependencies(RegisterArtifactRequest request) {
299	        return request.dependencies().stream()
300	                .map(d -> d.name().trim() + ":" + d.minimumVersion() + ":" + d.maximumVersion())
301	                .sorted()
302	                .reduce((a, b) -> a + "," + b)
303	                .orElse("");
304	    }
305	
306	    private List<DependencyView> toDependencyViews(List<?> raw) {
307	        TreeMap<String, DependencyView> sorted = new TreeMap<>();
308	        for (Object o : raw) {
309	            if (o instanceof com.example.starter.api.dto.DependencySpec spec) {
310	                sorted.put(spec.name().trim(), new DependencyView(
311	                        spec.name().trim(), spec.minimumVersion(), spec.maximumVersion()));
312	            } else if (o instanceof DependencyRange range) {
313	                sorted.put(range.name(), new DependencyView(
314	                        range.name(), range.minimumVersion(), range.maximumVersion()));
315	            }
316	        }
317	        return List.copyOf(sorted.values());
318	    }
319	
320	    private LockFileResponse toLockResponse(LockFileRow row, List<LockEntryRow> entries) {
321	        List<LockEntryResponse> entryViews = entries.stream()
322	                .map(e -> new LockEntryResponse(e.name(), e.version()))
323	                .toList();
324	        return new LockFileResponse(row.id(), row.rootName(), row.rootVersion(),
325	                row.repositoryVersion(), row.createdAt(), entryViews);
326	    }
327	
328	    private void requireRequestId(String requestId) {
329	        if (requestId == null || requestId.isBlank()) {
330	            throw ApiException.badRequest("缺少请求头 X-Request-Id");
331	        }
332	    }
333	
334	    private String writeJson(Object value) {
335	        try {
336	            return objectMapper.writeValueAsString(value);
337	        } catch (Exception e) {
338	            throw new IllegalStateException("响应序列化失败", e);
339	        }
340	    }
341	
342	    private <T> T readJson(String json, Class<T> type) {
343	        try {
344	            return objectMapper.readValue(json, type);
345	        } catch (Exception e) {
346	            throw new IllegalStateException("幂等响应反序列化失败", e);
347	        }
348	    }
349	
350	    private static String sha256(String input) {
351	        try {
352	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
353	            byte[] bytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
354	            StringBuilder sb = new StringBuilder(bytes.length * 2);
355	            for (byte b : bytes) {
356	                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
357	                sb.append(Character.forDigit(b & 0xF, 16));
358	            }
359	            return sb.toString();
360	        } catch (NoSuchAlgorithmException e) {
361	            throw new IllegalStateException(e);
362	        }
363	    }
364	}
