1	package com.example.starter.repo;
2	
3	import com.example.starter.domain.ArtifactVersion;
4	import com.example.starter.domain.DependencyRange;
5	import com.example.starter.domain.RepositorySnapshot;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.support.GeneratedKeyHolder;
8	import org.springframework.jdbc.support.KeyHolder;
9	import org.springframework.stereotype.Repository;
10	
11	import java.sql.PreparedStatement;
12	import java.sql.Statement;
13	import java.sql.Timestamp;
14	import java.time.Instant;
15	import java.util.ArrayList;
16	import java.util.LinkedHashMap;
17	import java.util.List;
18	import java.util.Map;
19	import java.util.stream.Collectors;
20	
21	/**
22	 * 仓库数据访问：制品、依赖、锁文件、仓库版本与幂等记录。
23	 *
24	 * <p>所有多语句业务操作均在 Service 层事务内执行；写事务通过
25	 * {@code SELECT ... FOR UPDATE} 锁定单行仓库版本表实现串行化，
26	 * 保证锁定与撤回并发时看到的版本号和快照一致。
27	 */
28	@Repository
29	public class RepositoryDao {
30	
31	    private final JdbcTemplate jdbcTemplate;
32	
33	    public RepositoryDao(JdbcTemplate jdbcTemplate) {
34	        this.jdbcTemplate = jdbcTemplate;
35	    }
36	
37	    /**
38	     * 锁定仓库版本单行并返回当前版本号；写事务入口调用，互斥其他写事务。
39	     */
40	    public long lockRepositoryState() {
41	        Long version = jdbcTemplate.queryForObject(
42	                "SELECT version FROM repository_state WHERE id = 1 FOR UPDATE", Long.class);
43	        return version == null ? 0L : version;
44	    }
45	
46	    /** 读取当前仓库版本号（不加锁，供查询使用）。 */
47	    public long getRepositoryVersion() {
48	        Long version = jdbcTemplate.queryForObject(
49	                "SELECT version FROM repository_state WHERE id = 1", Long.class);
50	        return version == null ? 0L : version;
51	    }
52	
53	    /**
54	     * 读取仓库一致性快照：全部制品版本（含撤回，版本号降序）及其依赖。
55	     * 须在已持有 repository_state 行锁的事务内调用。
56	     */
57	    public RepositorySnapshot loadSnapshot() {
58	        List<ArtifactRow> rows = jdbcTemplate.query(
59	                "SELECT id, name, version, withdrawn FROM artifact ORDER BY name ASC, version DESC",
60	                (rs, n) -> new ArtifactRow(rs.getLong("id"), rs.getString("name"),
61	                        rs.getInt("version"), rs.getInt("withdrawn") == 1));
62	
63	        List<DepRow> depRows = jdbcTemplate.query(
64	                "SELECT artifact_id, name, minimum_version, maximum_version FROM artifact_dependency",
65	                (rs, n) -> new DepRow(rs.getLong("artifact_id"), rs.getString("name"),
66	                        rs.getInt("minimum_version"), rs.getInt("maximum_version")));
67	        Map<Long, List<DependencyRange>> depsByArtifact = depRows.stream()
68	                .collect(Collectors.groupingBy(DepRow::artifactId,
69	                        Collectors.mapping(d -> new DependencyRange(d.name(), d.minimumVersion(), d.maximumVersion()),
70	                                Collectors.toList())));
71	
72	        Map<String, List<ArtifactVersion>> artifacts = new LinkedHashMap<>();
73	        for (ArtifactRow row : rows) {
74	            List<DependencyRange> deps = depsByArtifact.getOrDefault(row.id(), List.of());
75	            ArtifactVersion version = new ArtifactVersion(row.id(), row.name(), row.version(),
76	                    row.withdrawn(), List.copyOf(deps));
77	            artifacts.computeIfAbsent(row.name(), k -> new ArrayList<>()).add(version);
78	        }
79	        return new RepositorySnapshot(getRepositoryVersion(), Map.copyOf(artifacts));
80	    }
81	
82	    /** name+version 的制品版本是否已存在（含撤回版本）。 */
83	    public boolean artifactExists(String name, int version) {
84	        Integer count = jdbcTemplate.queryForObject(
85	                "SELECT COUNT(1) FROM artifact WHERE name = ? AND version = ?",
86	                Integer.class, name, version);
87	        return count != null && count > 0;
88	    }
89	
90	    /** 仓库中已登记的不同制品名称数量。 */
91	    public int countDistinctNames() {
92	        Integer count = jdbcTemplate.queryForObject(
93	                "SELECT COUNT(DISTINCT name) FROM artifact", Integer.class);
94	        return count == null ? 0 : count;
95	    }
96	
97	    /** 指定名称已登记的版本数量（含撤回）。 */
98	    public int countVersions(String name) {
99	        Integer count = jdbcTemplate.queryForObject(
100	                "SELECT COUNT(1) FROM artifact WHERE name = ?", Integer.class, name);
101	        return count == null ? 0 : count;
102	    }
103	
104	    /** 新增制品版本，返回自增主键。 */
105	    public long insertArtifact(String name, int version, Instant createdAt) {
106	        KeyHolder keyHolder = new GeneratedKeyHolder();
107	        jdbcTemplate.update(con -> {
108	            PreparedStatement ps = con.prepareStatement(
109	                    "INSERT INTO artifact (name, version, withdrawn, created_at) VALUES (?, ?, 0, ?)",
110	                    Statement.RETURN_GENERATED_KEYS);
111	            ps.setString(1, name);
112	            ps.setInt(2, version);
113	            ps.setTimestamp(3, Timestamp.from(createdAt));
114	            return ps;
115	        }, keyHolder);
116	        Number key = keyHolder.getKey();
117	        if (key == null) {
118	            throw new IllegalStateException("插入制品未获取自增主键");
119	        }
120	        return key.longValue();
121	    }
122	
123	    /** 为制品版本写入一条依赖声明。 */
124	    public void insertDependency(long artifactId, String name, int minimumVersion, int maximumVersion) {
125	        jdbcTemplate.update(
126	                "INSERT INTO artifact_dependency (artifact_id, name, minimum_version, maximum_version) "
127	                        + "VALUES (?, ?, ?, ?)",
128	                artifactId, name, minimumVersion, maximumVersion);
129	    }
130	
131	    /** 读取单个制品版本（含依赖），不存在返回 null。 */
132	    public ArtifactVersion loadArtifact(String name, int version) {
133	        List<ArtifactRow> rows = jdbcTemplate.query(
134	                "SELECT id, name, version, withdrawn FROM artifact WHERE name = ? AND version = ?",
135	                (rs, n) -> new ArtifactRow(rs.getLong("id"), rs.getString("name"),
136	                        rs.getInt("version"), rs.getInt("withdrawn") == 1),
137	                name, version);
138	        if (rows.isEmpty()) {
139	            return null;
140	        }
141	        ArtifactRow row = rows.get(0);
142	        List<DependencyRange> deps = jdbcTemplate.query(
143	                "SELECT name, minimum_version, maximum_version FROM artifact_dependency WHERE artifact_id = ?",
144	                (rs, n) -> new DependencyRange(rs.getString("name"),
145	                        rs.getInt("minimum_version"), rs.getInt("maximum_version")),
146	                row.id());
147	        return new ArtifactVersion(row.id(), row.name(), row.version(), row.withdrawn(),
148	                List.copyOf(deps));
149	    }
150	
151	    /** 仓库版本号加一，返回加一后的版本号（须在持有行锁时调用）。 */
152	    public long incrementRepositoryVersion() {
153	        jdbcTemplate.update("UPDATE repository_state SET version = version + 1 WHERE id = 1");
154	        return getRepositoryVersion();
155	    }
156	
157	    /**
158	     * 撤回指定制品版本，仅当当前未撤回时生效，返回受影响行数。
159	     * 条件更新保证重复撤回/并发撤回的原子判定。
160	     */
161	    public int markWithdrawn(long artifactId) {
162	        return jdbcTemplate.update(
163	                "UPDATE artifact SET withdrawn = 1 WHERE id = ? AND withdrawn = 0", artifactId);
164	    }
165	
166	    /** 新增锁文件主记录，返回自增主键。 */
167	    public long insertLockFile(String rootName, int rootVersion, long repositoryVersion,
168	                               String requestId, Instant createdAt) {
169	        KeyHolder keyHolder = new GeneratedKeyHolder();
170	        jdbcTemplate.update(con -> {
171	            PreparedStatement ps = con.prepareStatement(
172	                    "INSERT INTO lock_file (root_name, root_version, repository_version, request_id, created_at) "
173	                            + "VALUES (?, ?, ?, ?, ?)",
174	                    Statement.RETURN_GENERATED_KEYS);
175	            ps.setString(1, rootName);
176	            ps.setInt(2, rootVersion);
177	            ps.setLong(3, repositoryVersion);
178	            ps.setString(4, requestId);
179	            ps.setTimestamp(5, Timestamp.from(createdAt));
180	            return ps;
181	        }, keyHolder);
182	        Number key = keyHolder.getKey();
183	        if (key == null) {
184	            throw new IllegalStateException("插入锁文件未获取自增主键");
185	        }
186	        return key.longValue();
187	    }
188	
189	    /** 新增锁文件精确版本条目。 */
190	    public void insertLockEntry(long lockFileId, String name, int version) {
191	        jdbcTemplate.update(
192	                "INSERT INTO lock_file_entry (lock_file_id, name, version) VALUES (?, ?, ?)",
193	                lockFileId, name, version);
194	    }
195	
196	    /** 幂等记录视图。 */
197	    public record IdempotentRecord(String requestId, String operation, String requestHash,
198	                                   int httpStatus, String responseJson) {
199	    }
200	
201	    /**
202	     * 插入进行中的幂等占位记录（同事务内随后更新为完成态）。
203	     * requestId 冲突由唯一索引抛出 DuplicateKeyException。
204	     */
205	    public void insertPendingIdempotentRequest(String requestId, String operation, String requestHash,
206	                                               Instant createdAt) {
207	        jdbcTemplate.update(
208	                "INSERT INTO idempotent_request (request_id, operation, request_hash, http_status, "
209	                        + "response_json, created_at) VALUES (?, ?, ?, ?, CAST('' AS CHARACTER LARGE OBJECT), ?)",
210	                requestId, operation, requestHash, 0, Timestamp.from(createdAt));
211	    }
212	
213	    /** 将幂等记录更新为成功完成态，与业务变更在同一事务提交。 */
214	    public void completeIdempotentRequest(String requestId, int httpStatus, String responseJson) {
215	        jdbcTemplate.update(
216	                "UPDATE idempotent_request SET http_status = ?, response_json = ? WHERE request_id = ?",
217	                ps -> {
218	                    ps.setInt(1, httpStatus);
219	                    ps.setClob(2, new java.io.StringReader(responseJson));
220	                    ps.setString(3, requestId);
221	                });
222	    }
223	
224	    /** 按 requestId 查找已完成的成功幂等记录，不存在返回 null。 */
225	    public IdempotentRecord findIdempotentRequest(String requestId) {
226	        List<IdempotentRecord> records = jdbcTemplate.query(
227	                "SELECT request_id, operation, request_hash, http_status, response_json "
228	                        + "FROM idempotent_request WHERE request_id = ? AND http_status > 0",
229	                (rs, n) -> new IdempotentRecord(rs.getString("request_id"),
230	                        rs.getString("operation"), rs.getString("request_hash"),
231	                        rs.getInt("http_status"), rs.getString("response_json")),
232	                requestId);
233	        return records.isEmpty() ? null : records.get(0);
234	    }
235	
236	    /** 锁文件列表行：不含条目明细。 */
237	    public record LockFileRow(long id, String rootName, int rootVersion,
238	                              long repositoryVersion, Instant createdAt) {
239	    }
240	
241	    /** 锁文件条目行。 */
242	    public record LockEntryRow(long lockFileId, String name, int version) {
243	    }
244	
245	    /** 查询全部历史锁文件，按 ID 升序。 */
246	    public List<LockFileRow> listLockFiles() {
247	        return jdbcTemplate.query(
248	                "SELECT id, root_name, root_version, repository_version, created_at "
249	                        + "FROM lock_file ORDER BY id ASC",
250	                (rs, n) -> new LockFileRow(rs.getLong("id"), rs.getString("root_name"),
251	                        rs.getInt("root_version"), rs.getLong("repository_version"),
252	                        rs.getTimestamp("created_at").toInstant()));
253	    }
254	
255	    /** 按主键查询锁文件，不存在返回 null。 */
256	    public LockFileRow getLockFile(long id) {
257	        List<LockFileRow> rows = jdbcTemplate.query(
258	                "SELECT id, root_name, root_version, repository_version, created_at "
259	                        + "FROM lock_file WHERE id = ?",
260	                (rs, n) -> new LockFileRow(rs.getLong("id"), rs.getString("root_name"),
261	                        rs.getInt("root_version"), rs.getLong("repository_version"),
262	                        rs.getTimestamp("created_at").toInstant()),
263	                id);
264	        return rows.isEmpty() ? null : rows.get(0);
265	    }
266	
267	    /** 查询某锁文件的全部条目，按名称升序。 */
268	    public List<LockEntryRow> listLockEntries(long lockFileId) {
269	        return jdbcTemplate.query(
270	                "SELECT lock_file_id, name, version FROM lock_file_entry "
271	                        + "WHERE lock_file_id = ? ORDER BY name ASC",
272	                (rs, n) -> new LockEntryRow(rs.getLong("lock_file_id"),
273	                        rs.getString("name"), rs.getInt("version")),
274	                lockFileId);
275	    }
276	
277	    private record ArtifactRow(long id, String name, int version, boolean withdrawn) {
278	    }
279	
280	    private record DepRow(long artifactId, String name, int minimumVersion, int maximumVersion) {
281	    }
282	}
