    @Test
    void peerHostVersionMismatchFallsBackToCompatiblePlugin() {
        // 题干合成场景：根依赖宿主 h1 与插件 p[1,2]；p2 要求 h2，p1 要求 h1，应回退 p1。
        RepositorySnapshot s = snapshot(0,
                "root", List.of(v(1, dep("h", 1, 1), dep("p", 1, 2))),
