        assertThat(LockResolver.resolve(s, "root", 1))
                .isEqualTo(Map.of("h", 1, "p", 1, "root", 1));
    }

    @Test
    void peerCheckedAgainstEverySelectedPlugin() {
        // 根依赖 h[1,2] 与 p[1,1]；p1 的 peer 要求 h[2,2] → 宿主必须回退到 h2。
        RepositorySnapshot s = snapshot(0,
