                "h", List.of(v(2), v(1)),
                "p", List.of(vp(1, List.of(), dep("h", 2, 2))));

        assertThat(LockResolver.resolve(s, "root", 1))
                .isEqualTo(Map.of("h", 2, "p", 1, "root", 1));
    }
}

